package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

public class KeyedObjects2D_removeColumn_TriageGen0Test {

    private KeyedObjects2D dataset;
    private final Comparable ROW_KEY_1 = "Row1";
    private final Comparable COL_KEY_1 = "Col1";
    private final Comparable COL_KEY_2 = "Col2";
    private final Comparable UNKNOWN_KEY = "Unknown";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_UnknownKeyThrowsException() {
        // Test branch: index < 1 (throws UnknownKeyException)
        try {
            dataset.removeColumn(UNKNOWN_KEY);
            fail("Expected UnknownKeyException was not thrown");
        } catch (UnknownKeyException e) {
            assertEquals("Column key (" + UNKNOWN_KEY + ") not recognised.", e.getMessage());
        }
    }

    @Test
    public void testRemoveColumn_SuccessWithData() {
        // Setup data
        dataset.addObject("Val1", ROW_KEY_1, COL_KEY_1);
        dataset.addObject("Val2", ROW_KEY_1, COL_KEY_2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Val1", dataset.getObject(0, 0));
        assertEquals("Val2", dataset.getObject(0, 1));

        // Execute: remove the first column
        dataset.removeColumn(COL_KEY_1);

        // Verify column keys are updated
        assertEquals(1, dataset.getColumnCount());
        assertEquals(COL_KEY_2, dataset.getColumnKey(0));

        // Verify data removal from rows
        // After removing Col1, the remaining object should be at index 0 (Col2)
        assertEquals("Val2", dataset.getObject(0, 0));

        // Verify the specific object for Col1 is gone
        assertNull(dataset.getObject(ROW_KEY_1, COL_KEY_1));
    }

    @Test
    public void testRemoveColumn_RowDoesNotContainKey() {
        // Setup: Add a column, but a row that doesn't have that column key
        // Note: In most implementations of KeyedObjects2D, addObject adds the key.
        // To test the 'if (i >= 0)' branch, we simulate a scenario where a row 
        // exists in the dataset but its internal KeyedObjects doesn't contain the specific column key.

        dataset.addObject("Val1", ROW_KEY_1, COL_KEY_1);

        // We need to ensure the column exists in the dataset, but some row might not have it.
        // Since we can't easily inject a 'partial' row without internal access, 
        // we test the standard path where the key is valid for the dataset but 
        // if the iterator hits a row where getIndex returns -1.

        // However, given the provided API, the most robust way to test the logic 
        // is to ensure that when the column is valid, the columnKeys list is updated.
        dataset.removeColumn(COL_KEY_1);
        assertEquals(0, dataset.getColumnCount());
    }

    @Test
    public void testRemoveColumn_MultipleRows() {
        dataset.addObject("R1C1", ROW_KEY_1, COL_KEY_1);
        dataset.addObject("R2C1", "Row2", COL_KEY_1);
        dataset.addObject("R1C2", ROW_KEY_1, COL_KEY_2);

        dataset.removeColumn(COL_KEY_1);

        assertEquals(1, dataset.getColumnCount());
        assertEquals(COL_KEY_2, dataset.getColumnKey(0));
        assertEquals("R1C2", dataset.getObject(0, 0));
    }
}
